results.js:
const WORK = 25 * 60, BREAK = 5 * 60;
const st = { mode: 'work', left: WORK, running: false };
const fmt = s => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');

function render(box) {
  const t = box.querySelector('.pp-time');
  if (!t) return;
  t.textContent = (st.mode === 'work' ? '🍅 ' : '☕ ') + fmt(st.left) + (st.running ? '' : ' ⏸');
  box.className = st.mode;
  box.title = 'Pomodoro: click to ' + (st.running ? 'pause' : 'start');
}
function renderAll() { morse.$$('#morse-pomo').forEach(render); }

morse.every(1000, () => {
  if (!st.running) return;
  st.left--;
  if (st.left <= 0) {
    st.mode = st.mode === 'work' ? 'break' : 'work';
    st.left = st.mode === 'work' ? WORK : BREAK;
    morse.toast(st.mode === 'break' ? 'Time for a break!' : 'Back to work!');
  }
  renderAll();
});

morse.watch('#workbench\\.parts\\.statusbar .left-items', left => {
  const box = morse.el('div', { id: 'morse-pomo', class: 'work' },
    morse.el('span', { class: 'pp-time' }),
    morse.el('span', { class: 'pp-reset', text: '↺', title: 'Reset', on: { click: e => {
      e.stopPropagation();
      st.running = false; st.mode = 'work'; st.left = WORK; renderAll();
    } } })
  );
  box.addEventListener('click', () => { st.running = !st.running; renderAll(); });
  left.appendChild(box);
  render(box);
});

