const D = { work: 1500, break: 300 };
let mode = morse.store.get("pomoMode") || "work";
let left = D[mode];
let running = false;

const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");

function render() {
  const label = (mode === "work" ? "Focus " : "Break ") + fmt(left);
  morse.$$("#pomo-timer").forEach(i => {
    i.classList.toggle("pomo-break", mode === "break");
    const a = i.querySelector("a");
    a.setAttribute("aria-label", "Pomodoro " + label + (running ? " (click to pause)" : " (click to start)"));
    i.querySelector(".codicon").className = "codicon codicon-" + (running ? "debug-pause" : "play");
    i.querySelector(".pomo-text").textContent = label;
  });
}

function toggle() { running = !running; render(); }
function reset() {
  running = false; mode = "work"; left = D.work;
  morse.store.set("pomoMode", mode); render();
}

morse.every(1000, () => {
  if (!running) return;
  left--;
  if (left <= 0) {
    mode = mode === "work" ? "break" : "work";
    left = D[mode];
    morse.store.set("pomoMode", mode);
    morse.toast(mode === "break" ? "Focus session done. Take a 5 minute break." : "Break over. Time to focus.");
  }
  render();
});

const item = (id, icon, label, fn, text) => {
  const kids = [morse.el("span", { class: "codicon codicon-" + icon })];
  if (text) kids.push(morse.el("span", { class: "pomo-text" }));
  return morse.el("div", { class: "statusbar-item right has-command", id, "aria-label": label },
    morse.el("a", {
      class: "statusbar-item-label", role: "button", tabindex: "0", "aria-label": label,
      on: { click: fn, keydown: e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); fn(); } } }
    }, ...kids));
};

morse.watch("#workbench\\.parts\\.statusbar .right-items", c => {
  c.append(
    item("pomo-reset", "debug-restart", "Reset Pomodoro", reset, false),
    item("pomo-timer", "play", "Pomodoro", toggle, true)
  );
  render();
});

