results.js:
const S = { left: 25 * 60, run: false, brk: false };
const total = () => (S.brk ? 5 : 25) * 60;

function render() {
  const m = String(Math.floor(S.left / 60)).padStart(2, "0");
  const s = String(S.left % 60).padStart(2, "0");
  const label = (S.brk ? "Break " : "Focus ") + m + ":" + s;
  morse.$$("#pomo-timer").forEach(el => {
    el.classList.toggle("running", S.run);
    const text = el.querySelector(".pomo-text");
    if (text) text.textContent = label;
    const icon = el.querySelector(".codicon");
    if (icon) icon.className = "codicon " + (S.run ? "codicon-debug-pause" : "codicon-play");
    const a = el.querySelector("a");
    const tip = (S.run ? "Pause" : "Start") + " Pomodoro timer";
    a.setAttribute("aria-label", tip);
    el.setAttribute("aria-label", tip);
  });
  morse.$$("#pomo-reset").forEach(el =>
    el.classList.toggle("show", S.run || S.left !== total())
  );
}

function toggle() { S.run = !S.run; render(); }
function reset() { S.run = false; S.brk = false; S.left = total(); render(); }

function makeItem(id, iconName, label, onClick, withText) {
  const a = morse.el("a", { class: "statusbar-item-label", role: "button", tabindex: "0", "aria-label": label },
    morse.el("span", { class: "codicon " + iconName }),
    ...(withText ? [morse.el("span", { class: "pomo-text" })] : [])
  );
  const item = morse.el("div", { id, class: "statusbar-item right has-command", "aria-label": label, title: label }, a);
  a.addEventListener("click", onClick);
  a.addEventListener("keydown", e => {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onClick(); }
  });
  return item;
}

morse.watch(".part.statusbar .right-items", el => {
  el.append(
    makeItem("pomo-timer", "codicon-play", "Start Pomodoro timer", toggle, true),
    makeItem("pomo-reset", "codicon-debug-restart", "Reset Pomodoro timer", reset, false)
  );
  render();
});

morse.every(1000, () => {
  if (!S.run) return;
  S.left--;
  if (S.left <= 0) {
    morse.toast(S.brk ? "Break over. Ready to focus." : "Focus session done. Take a 5 minute break.");
    S.brk = !S.brk;
    S.left = total();
    S.run = false;
  }
  render();
});

morse.watch('#workbench\\.parts\\.statusbar .right-items', bar => {
  const a = morse.el('a', { class: 'statusbar-item-label', text: 'Words: 0' });
  const item = morse.el('div', { class: 'statusbar-item right', id: 'morse-wordcount' }, a);
  bar.appendChild(item);
  const update = () => {
    const lines = morse.$$('#workbench\\.parts\\.editor .editor-instance .view-lines .view-line');
    const text = lines.map(l => l.textContent.replace(/\u00a0/g, ' ')).join('\n');
    const n = (text.trim().match(/\S+/g) || []).length;
    a.textContent = 'Words: ' + n;
  };
  update();
  morse.every(500, update);
});

morse.watch("#workbench\\.parts\\.statusbar .right-items", el => {
  const label = morse.el("a", { class: "statusbar-item-label", role: "button", tabindex: "-1", "aria-label": "Word count", text: "0 words" });
  const item = morse.el("div", { class: "statusbar-item right has-command", id: "status.wordcount", "aria-label": "Word count" }, label);
  el.appendChild(item);
  const update = () => {
    const lines = morse.$$(".editor-instance .monaco-editor .view-lines .view-line");
    const text = lines
      .sort((a, b) => parseFloat(a.style.top) - parseFloat(b.style.top))
      .map(l => l.textContent.replace(/\u00a0/g, " "))
      .join("\n");
    const n = (text.match(/\S+/g) || []).length;
    label.textContent = n + (n === 1 ? " word" : " words");
  };
  update();
  morse.every(500, update);
});

morse.watch('#workbench\\.parts\\.statusbar .right-items', bar => {
  const label = morse.el('a', { class: 'statusbar-item-label', role: 'button', tabindex: '-1', text: '0 words' });
  const item = morse.el('div', { class: 'statusbar-item right', id: 'morse.wordcount', 'aria-label': 'Word count' }, label);
  bar.appendChild(item);
  const update = () => {
    const editor = document.querySelector('#workbench\\.parts\\.editor .monaco-editor .view-lines');
    if (!editor) { item.style.display = 'none'; return; }
    item.style.display = '';
    let n = 0;
    editor.querySelectorAll('.view-line').forEach(l => {
      const t = l.textContent.replace(/\u00a0/g, ' ').trim();
      if (t) n += t.split(/\s+/).length;
    });
    const text = n + (n === 1 ? ' word' : ' words');
    if (label.textContent !== text) label.textContent = text;
  };
  update();
  morse.every(500, update);
});

morse.watch('.editor-actions ul.actions-container[aria-label="Editor actions"]', ul => {
  const a = morse.el('a', {
    class: 'action-label codicon codicon-copy',
    role: 'button',
    tabindex: '0',
    title: 'Copy entire file',
    'aria-label': 'Copy entire file',
    on: {
      click: e => {
        e.preventDefault();
        const ta = morse.$$('.editor-group-container.active textarea.ime-text-area')[0] || morse.$$('textarea.ime-text-area')[0];
        if (!ta) { morse.toast('No editor found'); return; }
        ta.focus();
        ta.dispatchEvent(new KeyboardEvent('keydown', { key: 'a', code: 'KeyA', keyCode: 65, which: 65, ctrlKey: true, bubbles: true, cancelable: true }));
        ta.dispatchEvent(new KeyboardEvent('keyup', { key: 'a', code: 'KeyA', keyCode: 65, which: 65, ctrlKey: true, bubbles: true }));
        setTimeout(() => {
          const ok = document.execCommand('copy');
          morse.toast(ok ? 'File copied to clipboard' : 'Copy failed');
        }, 50);
      }
    }
  });
  const li = morse.el('li', { class: 'action-item morse-copy-all', role: 'presentation' }, a);
  ul.insertBefore(li, ul.firstChild);
});

morse.watch('.editor-group-container.active ul.actions-container[aria-label="Editor actions"]', ul => {
  const btn = morse.el('a', {
    class: 'action-label codicon codicon-copy',
    role: 'button',
    tabindex: '0',
    'aria-label': 'Copy Entire File',
    title: 'Copy Entire File'
  });
  const run = async () => {
    const group = ul.closest('.editor-group-container');
    const lines = [...group.querySelectorAll('.monaco-editor .view-lines .view-line')]
      .sort((a, b) => parseFloat(a.style.top) - parseFloat(b.style.top))
      .map(l => l.textContent.replace(/\u00a0/g, ' '));
    if (!lines.length) return morse.toast('Nothing to copy');
    try {
      await navigator.clipboard.writeText(lines.join('\n'));
      morse.toast('File copied');
    } catch (e) {
      morse.toast('Copy failed');
    }
  };
  morse.on(btn, 'click', run);
  morse.on(btn, 'keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); run(); }
  });
  const li = morse.el('li', { class: 'action-item menu-entry', role: 'presentation' }, btn);
  ul.prepend(li);
  return () => li.remove();
});

morse.watch('.editor-group-container ul[aria-label="Editor actions"]', ul => {
  const copy = () => {
    const group = ul.closest('.editor-group-container');
    const lines = morse.$$('.monaco-editor .view-lines .view-line').filter(l => group.contains(l));
    const byTop = new Map();
    lines.forEach(l => byTop.set(parseFloat(l.style.top) || 0, l.textContent.replace(/\u00a0/g, ' ')));
    const text = [...byTop.entries()].sort((a, b) => a[0] - b[0]).map(e => e[1]).join('\n');
    if (!text) return morse.toast('Nothing to copy');
    navigator.clipboard.writeText(text).then(
      () => morse.toast('Copied ' + byTop.size + ' lines'),
      () => morse.toast('Copy failed')
    );
  };
  const a = morse.el('a', {
    class: 'action-label codicon codicon-copy',
    role: 'button',
    'aria-label': 'Copy Whole File',
    tabindex: '0',
    on: {
      click: copy,
      keydown: e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); copy(); } }
    }
  });
  const li = morse.el('li', { class: 'action-item menu-entry', role: 'presentation', title: 'Copy Whole File' }, a);
  ul.insertBefore(li, ul.firstChild);
  return () => li.remove();
});

