const LEN = { work: 1500, rest: 300 };
const saved = morse.store.get("pomo") || {};
const st = { mode: saved.mode || "work", left: saved.left || LEN.work, running: false };

const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
const save = () => morse.store.set("pomo", { mode: st.mode, left: st.left });

function render() {
  morse.$$(".morse-pomo").forEach(w => {
    w.classList.toggle("is-running", st.running);
    w.classList.toggle("is-break", st.mode === "rest");
    w.querySelector(".morse-pomo-time").textContent = fmt(st.left);
    w.querySelector(".morse-pomo-label").textContent = st.mode === "work" ? "Focus" : "Break";
    w.setAttribute("aria-label", st.running ? "Pause timer" : "Start timer");
  });
}

morse.every(1000, () => {
  if (!st.running) return;
  st.left--;
  if (st.left <= 0) {
    st.mode = st.mode === "work" ? "rest" : "work";
    st.left = LEN[st.mode];
    st.running = false;
    morse.toast(st.mode === "rest" ? "Focus done. Time for a break." : "Break over. Ready to focus?");
  }
  save();
  render();
});

morse.watch(".status-bar", bar => {
  const icon = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="svg-icon lucide-timer"><line x1="10" x2="14" y1="2" y2="2"/><line x1="12" x2="15" y1="14" y2="11"/><circle cx="12" cy="14" r="8"/></svg>';
  const resetIcon = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="svg-icon lucide-rotate-ccw"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>';
  const wrap = morse.el("div", {
    class: "status-bar-item mod-clickable morse-pomo",
    role: "button",
    tabindex: "0",
    on: {
      click: e => {
        if (e.target.closest(".morse-pomo-reset")) return;
        st.running = !st.running;
        render();
      },
      keydown: e => {
        if ((e.key === "Enter" || e.key === " ") && !e.target.closest(".morse-pomo-reset")) {
          e.preventDefault();
          st.running = !st.running;
          render();
        }
      }
    }
  },
    morse.el("span", { class: "status-bar-item-icon", html: icon }),
    morse.el("span", { class: "morse-pomo-label" }),
    morse.el("span", { class: "morse-pomo-time" }),
    morse.el("button", {
      class: "morse-pomo-reset",
      "aria-label": "Reset timer",
      html: resetIcon,
      on: {
        click: () => {
          st.running = false;
          st.left = LEN[st.mode];
          save();
          render();
        }
      }
    })
  );
  bar.prepend(wrap);
  render();
});

