morse.watch('.workspace-leaf-content[data-type="markdown"] .view-content', vc => {
  if (!vc.querySelector(':scope > .morse-progress')) {
    vc.appendChild(morse.el('div', { class: 'morse-progress', role: 'progressbar', 'aria-label': 'Reading progress' },
      morse.el('div', { class: 'morse-progress-fill' })));
  }
});
morse.watch('.workspace-leaf-content[data-type="markdown"] .view-content .cm-scroller, .workspace-leaf-content[data-type="markdown"] .view-content .markdown-preview-view', s => {
  const update = () => {
    const bar = s.closest('.view-content')?.querySelector(':scope > .morse-progress');
    const fill = bar?.firstElementChild;
    if (!fill) return;
    const max = s.scrollHeight - s.clientHeight;
    const pct = max > 0 ? Math.min(100, s.scrollTop / max * 100) : 0;
    fill.style.width = pct + '%';
    bar.setAttribute('aria-valuenow', Math.round(pct));
  };
  morse.on(s, 'scroll', update);
  update();
});

morse.watch('.note-title-wrapper', wrap => {
  const label = morse.el('span', { class: 'word-count-label', text: '' });
  const info = wrap.querySelector('.note-title-info-group');
  wrap.insertBefore(label, info);
  const update = () => {
    const c = document.querySelector('.cm-content');
    let text = '';
    try { text = c.cmView.view.state.doc.toString(); } catch (e) { text = c ? c.innerText : ''; }
    const n = (text.match(/\S+/g) || []).length;
    label.textContent = n + (n === 1 ? ' word' : ' words');
  };
  update();
  morse.every(500, update);
});

function getText() {
  const c = document.querySelector('.cm-content');
  const view = c && c.cmView && c.cmView.view;
  if (view) return view.state.doc.toString();
  return c ? c.innerText : null;
}
morse.watch('.note-title-info-group', el => {
  const time = el.querySelector('.updated-time-label');
  const badge = morse.el('span', { class: 'updated-time-label', 'data-word-count': '' });
  if (time) badge.style.cssText = time.style.cssText;
  badge.style.marginRight = '10px';
  badge.style.whiteSpace = 'nowrap';
  el.insertBefore(badge, el.firstChild);
  const update = () => {
    const t = getText();
    if (t === null) { badge.hidden = true; return; }
    badge.hidden = false;
    const n = t.trim().split(/\s+/).filter(Boolean).length;
    badge.textContent = n + (n === 1 ? ' word' : ' words');
  };
  update();
  morse.every(500, update);
});

