morse.watch('div[aria-label="Sidebar"] > div:nth-of-type(2)', host => {
  const W = 25*60, R = 5*60;
  let mode = 'work', left = W, running = false;
  const fmt = s => String(Math.floor(s/60)).padStart(2,'0') + ':' + String(s%60).padStart(2,'0');
  const time = morse.el('div', {class:'t', text:fmt(left)});
  const label = morse.el('div', {class:'m', text:'Focus'});
  const go = morse.el('button', {text:'Start', on:{click:()=>{running=!running; render();}}});
  const reset = morse.el('button', {text:'Reset', on:{click:()=>{running=false; left=mode==='work'?W:R; render();}}});
  const box = morse.el('div', {class:'morse-pomo work'}, label, time, morse.el('div', {class:'b'}, go, reset));
  function render(){
    time.textContent = fmt(left);
    label.textContent = mode==='work' ? 'Focus' : 'Break';
    go.textContent = running ? 'Pause' : 'Start';
    box.className = 'morse-pomo ' + mode;
  }
  host.insertBefore(box, host.firstChild);
  morse.every(1000, () => {
    if (!running) return;
    left--;
    if (left <= 0) {
      mode = mode==='work' ? 'rest' : 'work';
      left = mode==='work' ? W : R;
      morse.toast(mode==='work' ? 'Break over: time to focus' : 'Pomodoro done: take a break');
    }
    render();
  });
});

