const LEN = { Focus: 25 * 60, Break: 5 * 60 };
const state = { mode: 'Focus', left: LEN.Focus, running: false };

morse.watch('div[aria-label="Sidebar"] > div:nth-of-type(2)', host => {
  const sync = host.querySelector('[class*="sidebar-sync-button"]') || host.lastElementChild;
  const modeBtn = morse.el('button', { class: 'morse-pomo-mode', title: 'Switch focus/break', 'aria-label': 'Switch focus or break' });
  const time = morse.el('span', { class: 'morse-pomo-time', role: 'timer' });
  const icon = morse.el('i', { class: 'fas fa-play' });
  const toggle = morse.el('button', { class: 'morse-pomo-btn', 'aria-label': 'Start or pause timer', title: 'Start / pause' }, icon);
  const reset = morse.el('button', { class: 'morse-pomo-btn', 'aria-label': 'Reset timer', title: 'Reset' }, morse.el('i', { class: 'fas fa-redo' }));
  const box = morse.el('div', { class: 'morse-pomo' }, modeBtn, time, toggle, reset);

  const render = () => {
    const m = String(Math.floor(state.left / 60)).padStart(2, '0');
    const s = String(state.left % 60).padStart(2, '0');
    time.textContent = m + ':' + s;
    modeBtn.textContent = state.mode;
    icon.className = 'fas ' + (state.running ? 'fa-pause' : 'fa-play');
    box.classList.toggle('-running', state.running);
  };

  morse.on(toggle, 'click', () => { state.running = !state.running; render(); });
  morse.on(reset, 'click', () => { state.running = false; state.left = LEN[state.mode]; render(); });
  morse.on(modeBtn, 'click', () => {
    state.mode = state.mode === 'Focus' ? 'Break' : 'Focus';
    state.running = false;
    state.left = LEN[state.mode];
    render();
  });
  morse.every(1000, () => {
    if (state.running) {
      state.left--;
      if (state.left <= 0) {
        state.running = false;
        morse.toast(state.mode === 'Focus' ? 'Focus session done. Take a break!' : 'Break over. Back to work!');
        state.mode = state.mode === 'Focus' ? 'Break' : 'Focus';
        state.left = LEN[state.mode];
      }
    }
    render();
  });

  host.insertBefore(box, sync);
  render();
});

