const S = { mode: 'work', left: 25 * 60, running: false, done: morse.store.get('pomoDone') || 0, ui: null };
const fmt = s => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
function render() {
  const u = S.ui; if (!u) return;
  u.box.classList.toggle('-break', S.mode === 'break');
  u.time.textContent = fmt(S.left);
  u.mode.textContent = (S.mode === 'work' ? 'Focus' : 'Break') + ' · ' + S.done + ' done';
  u.btn.innerHTML = '<i class="fas ' + (S.running ? 'fa-pause' : 'fa-play') + '"></i>';
  u.btn.setAttribute('aria-label', S.running ? 'Pause timer' : 'Start timer');
}
morse.every(1000, () => {
  if (!S.running) return;
  S.left--;
  if (S.left <= 0) {
    if (S.mode === 'work') { S.done++; morse.store.set('pomoDone', S.done); S.mode = 'break'; S.left = 5 * 60; morse.toast('Focus session done. Take a break!'); }
    else { S.mode = 'work'; S.left = 25 * 60; morse.toast('Break over. Back to work!'); }
  }
  render();
});
morse.watch('div[aria-label="Sidebar"] > div:nth-of-type(2)', el => {
  const mode = morse.el('span', { class: 'mp-mode' });
  const time = morse.el('span', { class: 'mp-time' });
  const btn = morse.el('button', { type: 'button', on: { click: () => { S.running = !S.running; render(); } } });
  const reset = morse.el('button', { type: 'button', title: 'Reset timer', 'aria-label': 'Reset timer', html: '<i class="fas fa-redo"></i>', on: { click: () => { S.running = false; S.mode = 'work'; S.left = 25 * 60; render(); } } });
  const box = morse.el('div', { class: 'morse-pomo' }, mode, time, btn, reset);
  S.ui = { box, mode, time, btn };
  el.insertBefore(box, el.querySelector('.sidebar-sync-button, button:last-child'));
  render();
});

