morse.watch('.note-title-wrapper', wrap => {
  const input = wrap.querySelector('input.title-input');
  if (!input) return;
  const btn = morse.el('button', {
    class: 'copy-title-btn',
    title: 'Copy title',
    'aria-label': 'Copy title',
    type: 'button',
    on: { click: async () => {
      const text = input.value;
      try { await navigator.clipboard.writeText(text); }
      catch (e) {
        const t = morse.el('textarea', { style: 'position:fixed;opacity:0' });
        t.value = text; document.body.appendChild(t); t.select();
        document.execCommand('copy'); t.remove();
      }
      morse.toast('Title copied');
    } }
  }, morse.el('i', { class: 'fas fa-copy', 'aria-hidden': 'true' }));
  input.after(btn);
});

morse.watch('.note-title-wrapper', wrap => {
  const input = wrap.querySelector('input.title-input');
  const info = wrap.querySelector('.note-title-info-group');
  if (!input || !info) return;
  const icon = morse.el('i', { class: 'toolbar-icon fas fa-copy', 'aria-hidden': 'true' });
  const btn = morse.el('button', {
    class: 'button toolbar-button copy-title-btn',
    title: 'Copy note title',
    'aria-label': 'Copy note title',
    type: 'button',
    on: {
      click: async () => {
        try {
          await navigator.clipboard.writeText(input.value);
          icon.className = 'toolbar-icon fas fa-check';
          setTimeout(() => { icon.className = 'toolbar-icon fas fa-copy'; }, 1200);
        } catch (e) {
          morse.toast('Could not copy title');
        }
      }
    }
  }, icon);
  wrap.insertBefore(btn, info);
  return () => btn.remove();
});

