let q = "";
const apply = () => {
  let shown = 0;
  morse.$$("#column2 ul li").forEach(li => {
    const ok = !q || li.textContent.toLowerCase().includes(q);
    li.style.display = ok ? "" : "none";
    if (ok) shown++;
  });
  const e = document.querySelector("#column2 .nav-filter-empty");
  if (e) e.classList.toggle("show", shown === 0);
};
morse.watch("#column2", nav => {
  const input = morse.el("input", {
    type: "search",
    placeholder: "Filter pages…",
    "aria-label": "Filter pages",
    on: { input: ev => { q = ev.target.value.trim().toLowerCase(); apply(); } }
  });
  const box = morse.el("div", { class: "nav-filter" }, input);
  const empty = morse.el("div", { class: "nav-filter-empty", text: "No matching pages" });
  const intro = nav.querySelector("#intro");
  if (intro) { intro.after(box); box.after(empty); }
  else { nav.prepend(empty); nav.prepend(box); }
});
morse.watch("#column2 ul li", apply);

