results.js:
morse.watch('#column2', nav => {
  if (nav.querySelector('.morse-filter')) return;
  const input = morse.el('input', { type: 'search', placeholder: 'Filter pages…', 'aria-label': 'Filter pages' });
  const box = morse.el('div', { class: 'morse-filter' }, input);
  nav.insertBefore(box, nav.firstChild);
  const apply = () => {
    const q = input.value.trim().toLowerCase();
    nav.querySelectorAll('ul li').forEach(li => {
      li.classList.toggle('morse-hidden', !!q && !li.textContent.toLowerCase().includes(q));
    });
    morse.store.set('navFilter', input.value);
  };
  input.addEventListener('input', apply);
  input.addEventListener('keydown', e => { if (e.key === 'Escape') { input.value = ''; apply(); } });
  input.value = morse.store.get('navFilter') || '';
  apply();
});

